from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if r in (r0, r1):
            left, right = c0, c1
        elif len(cols) >= 4:
            left, right = min(cols), max(cols)
        else:
            continue
        for c in range(left, right + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
        if c in (c0, c1):
            top, bottom = r0, r1
        elif len(rows) >= 4:
            top, bottom = min(rows), max(rows)
        else:
            continue
        for r in range(top, bottom + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    return out
